import { useState } from 'react';
import { Combobox, type ListboxOption } from '@design-schema/react';

const FRUITS: ListboxOption[] = [
  { value: 'apple', label: 'Apple' },
  { value: 'apricot', label: 'Apricot' },
  { value: 'banana', label: 'Banana' },
  { value: 'blueberry', label: 'Blueberry' },
  { value: 'cherry', label: 'Cherry' },
  { value: 'grape', label: 'Grape' },
  { value: 'mango', label: 'Mango' },
  { value: 'papaya', label: 'Papaya' },
];

function AsyncDemo() {
  const [options, setOptions] = useState(FRUITS.slice(0, 3));
  const [loading, setLoading] = useState(false);
  return (
    <Combobox
      label="Fruit"
      name="fruit"
      filter="async"
      options={options}
      loading={loading}
      onInputChange={(text) => {
        setLoading(true);
        setTimeout(() => {
          setOptions(FRUITS.filter((option) => 'label' in option && option.label.toLowerCase().includes(text.toLowerCase())));
          setLoading(false);
        }, 300);
      }}
    />
  );
}

<AsyncDemo />

